UPDATE /*LGVATT50050.updateKoreanLeaderInfo*/
       TB_ATT_KOREAN_LEADER_N
SET    
	   employee_number                 = #{employeeNumber}
	 , mail_addr                       = #{mailAddr}
     , english_full_name               = #{englishFullName}
     , local_language_full_name        = #{localLanguageFullName}
     , organization_id                 = #{organizationId}
     , organization_name               = #{organizationName}
     , english_organization_name       = #{englishOrganizationName}
WHERE  employee_number                 = #{oldEmployeeNumber}
  AND  organization_id                 = #{oldOrganizationId}

